-- Name: sample_storage_assignment; Type: TABLE; Schema: clinlims; Owner: clinlims
--

CREATE TABLE clinlims.sample_storage_assignment (
    id numeric(10,0) NOT NULL,
    sample_item_id numeric(10,0) NOT NULL,
    location_id numeric(10,0),
    location_type character varying(20),
    position_coordinate character varying(50),
    assigned_by_user_id numeric(10,0) NOT NULL,
    assigned_date timestamp without time zone DEFAULT now() NOT NULL,
    notes text,
    last_updated timestamp without time zone,
    CONSTRAINT chk_location_type_valid CHECK (((location_type IS NULL) OR ((location_type)::text = ANY ((ARRAY['device'::character varying, 'shelf'::character varying, 'rack'::character varying, 'box'::character varying])::text[]))))
);


ALTER TABLE clinlims.sample_storage_assignment OWNER TO clinlims;

